using Microsoft.EntityFrameworkCore.Metadata.Conventions;
using Microsoft.EntityFrameworkCore.Metadata.Conventions.Infrastructure;

namespace Mapepire.EntityFrameworkCore.Metadata.Internal;

/// <summary>Annotation names used by the provider.</summary>
public static class MapepireAnnotationNames
{
    public const string Prefix = "Mapepire:";

    /// <summary>Marks a column as <c>GENERATED BY DEFAULT AS IDENTITY</c>.</summary>
    public const string Identity = Prefix + "Identity";
}

/// <summary>
/// Adds the <see cref="MapepireAnnotationNames.Identity"/> annotation to integer primary key columns
/// whose values are generated on add, so migrations create them as identity columns.
/// </summary>
public class MapepireAnnotationProvider(RelationalAnnotationProviderDependencies dependencies)
    : RelationalAnnotationProvider(dependencies)
{
    /// <inheritdoc />
    public override IEnumerable<IAnnotation> For(IColumn column, bool designTime)
    {
        foreach (var annotation in base.For(column, designTime))
        {
            yield return annotation;
        }

        if (IsIdentity(column))
        {
            yield return new Annotation(MapepireAnnotationNames.Identity, "1, 1");
        }
    }

    /// <summary>Whether the column should be created as an identity column.</summary>
    public static bool IsIdentity(IColumn column)
    {
        var table = column.Table;
        var storeObject = StoreObjectIdentifier.Table(table.Name, table.Schema);
        foreach (var mapping in column.PropertyMappings)
        {
            var property = mapping.Property;
            if (IsIdentityCandidate(property, storeObject))
            {
                return true;
            }
        }

        return false;
    }

    internal static bool IsIdentityCandidate(IReadOnlyProperty property, StoreObjectIdentifier storeObject)
    {
        if (property.ValueGenerated != ValueGenerated.OnAdd
            || property.IsForeignKey()
            || property.GetDefaultValueSql(storeObject) != null
            || property.TryGetDefaultValue(storeObject, out _)
            || property.GetComputedColumnSql(storeObject) != null)
        {
            return false;
        }

        var pk = property.DeclaringType.ContainingEntityType.FindPrimaryKey();
        if (pk == null || pk.Properties.Count != 1 || pk.Properties[0] != property)
        {
            return false;
        }

        var type = (property.GetValueConverter()?.ProviderClrType ?? property.GetTypeMapping().ClrType).UnwrapNullableType();
        return type == typeof(int) || type == typeof(long) || type == typeof(short);
    }
}

/// <summary>Convention set for the provider (relational defaults).</summary>
public class MapepireConventionSetBuilder(
    ProviderConventionSetBuilderDependencies dependencies,
    RelationalConventionSetBuilderDependencies relationalDependencies)
    : RelationalConventionSetBuilder(dependencies, relationalDependencies);

internal static class TypeExtensions
{
    public static Type UnwrapNullableType(this Type type) => Nullable.GetUnderlyingType(type) ?? type;
}
